const list = [10, 20, 30, 40, 50];
// slice(start, end) - non-mutating
const sub = list.slice(1, 3); // [20, 30], original untouched

// splice(start, deleteCount, ...items) - mutating
const removed = list.splice(1, 2); // returns [20, 30], list is now [10, 40, 50]

const config = { port: 8080, host: undefined };
const { port: serverPort, host = 'localhost', ssl = false } = config;
