// Rest parameter gathers args into array
function calculateSum(multiplier, ...numbers) {
  return numbers.reduce((sum, n) => sum + n, 0) * multiplier;
}
console.log(calculateSum(2, 1, 2, 3)); // (1+2+3)*2 = 12

// Spread operator merges objects
const base = { theme: 'dark', size: 'md' };
const custom = { size: 'lg' };
const config = { ...base, ...custom }; // { theme: 'dark', size: 'lg' }

const numbers = [1, 2, 3, 4, 5, 6];
const sumDoubledEvens = numbers
  .filter(n => n % 2 === 0)
  .map(n => n * 2)
  .reduce((acc, val) => acc + val, 0);

console.log(sumDoubledEvens); // 2 + 4 + 6 = 12 -> *2 -> 4+8+12 = 24

greet(); // 'Hello!'
function greet() { console.log('Hello!'); }

try {
  sayBye(); // TypeError: sayBye is not a function
} catch (e) { console.log(e.message); }
var sayBye = function() { console.log('Bye!'); };

function createCounter() {
  let count = 0;
  return {
    increment: () => ++count,
    getCount: () => count
  };
}
const counter = createCounter();
console.log(counter.increment()); // 1
console.log(counter.getCount()); // 1

const user = {
  name: 'Alex',
  regularFn: function() { console.log(this.name); },
  arrowFn: () => { console.log(this?.name); }
};
user.regularFn(); // 'Alex'
user.arrowFn(); // undefined (or global scope)

function greet(greeting, punctuation) {
  console.log(`${greeting}, ${this.name}${punctuation}`);
}
const person = { name: 'Sarah' };
greet.call(person, 'Hello', '!'); // 'Hello, Sarah!'
greet.apply(person, ['Hi', '.']); // 'Hi, Sarah.'
const boundFn = greet.bind(person, 'Hey');
boundFn('?'); // 'Hey, Sarah?'

function Animal(name) { this.name = name; }
Animal.prototype.speak = function() { return `${this.name} makes noise.`; };

const dog = new Animal('Rex');
console.log(dog.speak()); // 'Rex makes noise.'
console.log(dog.hasOwnProperty('name')); // true
console.log(dog.hasOwnProperty('speak')); // false (on prototype)

class Vehicle {
  #id;
  constructor(id) { this.#id = id; }
  getId() { return this.#id; }
}
class Car extends Vehicle {
  constructor(id, model) {
    super(id);
    this.model = model;
  }
}
const c = new Car(101, 'Tesla');
console.log(c.getId()); // 101
console.log(c.model); // 'Tesla'

// math.js - Named exports
export const add = (a, b) => a + b;
export const multiply = (a, b) => a * b;

// main.js - Import named exports and dynamic import
import { add, multiply } from './math.js';
console.log(add(2, 3)); // 5

// Dynamic import
import('./math.js').then(module => {
  console.log(module.multiply(4, 2)); // 8
});

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

try {
  throw new ValidationError('Invalid email format');
} catch (err) {
  if (err instanceof ValidationError) {
    console.log(`[${err.statusCode}] ${err.name}: ${err.message}`);
  } else {
    throw err;
  }
}

const fetchData = () => {
  return new Promise((resolve, reject) => {
    setTimeout(() => resolve({ status: 'ok', data: [1, 2, 3] }), 100);
  });
};

fetchData()
  .then(res => res.data)
  .then(items => console.log('Items:', items)) // Items: [1, 2, 3]
  .catch(err => console.error('Error:', err))
  .finally(() => console.log('Operation complete.'));

async function getUserData(userId) {
  try {
    const response = await fetch(`https://api.example.com/users/${userId}`);
    if (!response.ok) throw new Error(`HTTP Error: ${response.status}`);
    const user = await response.json();
    return user;
  } catch (err) {
    console.error('Failed to load user:', err.message);
    throw err;
  }
}

const p1 = Promise.resolve('Success 1');
const p2 = Promise.reject('Error 2');
const p3 = Promise.resolve('Success 3');

// Promise.allSettled waits for all outcomes
Promise.allSettled([p1, p2, p3]).then(results => {
  console.log(results);
  // [{status:'fulfilled', value:'Success 1'}, {status:'rejected', reason:'Error 2'}, ...]
});

// Promise.all fails fast on p2 rejection
Promise.all([p1, p2, p3]).catch(err => console.log('Failing fast:', err)); // 'Error 2'

