let element = document.createElement('div');
const metaMap = new WeakMap();

metaMap.set(element, { clicks: 42 });
console.log(metaMap.get(element)); // { clicks: 42 }

// When DOM element is removed and dereferenced:
element = null;
// Garbage collector automatically reclaims element and its metadata from WeakMap!

// MEMORY LEAK PATTERN:
function startLeak() {
  const hugeData = new Array(1000000).fill('leak');
  setInterval(() => {
    console.log(hugeData.length);
  }, 1000); // hugeData captured in closure forever!
}

// PROPER CLEANUP PATTERN:
function startClean() {
  const hugeData = new Array(1000000).fill('clean');
  const timerId = setInterval(() => {
    console.log(hugeData.length);
  }, 1000);
  return () => clearInterval(timerId); // Cleanup function destroys interval & closure reference!
}
